80	/**
81	 * Build a deeply-nested Supabase mock that correctly handles the chained
82	 * query builder pattern used by charges.ts:
83	 *
84	 *   studios:                  .from().select().eq().single()
85	 *   stripe_connected_accounts: .from().select().eq().eq().single()
86	 */
87	function makeSupabaseMock(opts: {
88	  rpcResponses?: RpcCallMap
89	  studioCountry?: string | null
90	  accountCountry?: string | null
91	  stripeChargeError?: { message: string } | null
92	}): SupabaseClient {
93	  const rpcResponses: RpcCallMap = opts.rpcResponses ?? {}
94	
95	  // Default RPC mock — returns success unless overridden
96	  const rpcMock = vi.fn(async (fn: string) => {
97	    if (fn in rpcResponses) return rpcResponses[fn]
98	    if (fn === RPC.APPLY_DEPOSIT_TO_SESSION) {
99	      return {
100	        data: {
101	          transaction_id: 'txn-test-001',
102	          pool_in_cents: 40000,
103	          pool_applied_cents: 20000,
104	          pool_available_cents: 20000,
105	        },
106	        error: null,
107	      }
108	    }
109	    if (fn === RPC.ROLLBACK_DEPOSIT_APPLICATION) {
110	      return { data: { transaction_id: 'txn-test-001', status: 'rolled_back', pool_available_cents: 40000 }, error: null }
111	    }
112	    if (fn === RPC.STRIPE_CHARGE_RECORD) {
113	      return { data: { id: 'charge-row-001', created: true }, error: null }
114	    }
115	    return { data: null, error: null }
116	  })
117	
118	  // Inline terminal factory — returns a consistent single() responder
119	  function makeSingle<T>(data: T, error: { message: string } | null = null) {
120	    return { single: vi.fn(async () => ({ data, error })) }
121	  }
122	
123	  // from() mock for country alignment check used in ensureCountryAligned()
124	  // Convention:
125	  //   studioCountry/accountCountry absent from opts → default success with 'US'
126	  //   studioCountry/accountCountry = null          → return data: { country: null } (triggers country_missing)
127	  //   studioCountry/accountCountry = 'XX'          → return that value (triggers drift if different)
128	  //   FORCE_ERROR sentinel (handled below)
129	  const MISSING_SENTINEL = '__MISSING__'
130	  const studioCountryVal = 'studioCountry' in opts ? opts.studioCountry : 'US'
131	  const accountCountryVal = 'accountCountry' in opts ? opts.accountCountry : 'US'
132	
133	  const fromMock = vi.fn((table: string) => {
134	    if (table === 'studios') {
135	      const studioData = studioCountryVal === MISSING_SENTINEL ? null : { country: studioCountryVal }
136	      const studioError = studioCountryVal === MISSING_SENTINEL ? { message: 'Not found' } : null
137	      return {
138	        select: vi.fn(() => ({
139	          eq: vi.fn(() => makeSingle(studioData, studioError)),
140	        })),
141	      }
142	    }
143	    if (table === 'stripe_connected_accounts') {
144	      const accData = accountCountryVal === MISSING_SENTINEL ? null : { country: accountCountryVal ?? 'US' }
145	      const accError = accountCountryVal === MISSING_SENTINEL ? { message: 'Not found' } : null
146	      return {
147	        select: vi.fn(() => ({
148	          eq: vi.fn(() => ({
149	            eq: vi.fn(() => makeSingle(accData, accError)),
150	          })),
151	        })),
152	      }
153	    }
154	    // Fallback for any other table
155	    return {
156	      select: vi.fn(() => ({
157	        eq: vi.fn(() => ({
158	          eq: vi.fn(() => ({ single: vi.fn(async () => ({ data: null, error: null })) })),
159	          single: vi.fn(async () => ({ data: null, error: null })),
160	        })),
161	      })),
162	    }
163	  })
164	
165	  return { rpc: rpcMock, from: fromMock } as unknown as SupabaseClient
166	}
